def list_accounts():
    composio = Composio()
    user_id = 'zealt-user01'
    response = composio.connected_accounts.list(user_ids=[user_id])
    print(f"Response type: {type(response)}")
    print(f"Response attributes: {dir(response)}")

    # Try to find the list of accounts
